package com.vigilante.app;
import android.app.*;
import android.os.Bundle;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.concurrent.*;
import java.util.*;

public final class BusinessActivity extends Activity {
 private static final int BG=0xff0a101f,CARD=0xff162137,BORDER=0xff30425e,WHITE=0xfff1f6ff,MUTED=0xffa7b9d5,BLUE=0xff3e7be7,GREEN=0xff63ddad;
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private LinearLayout root; private ScrollView scroll; private String selected="",filter="",quickSection=""; private boolean busy=false,refreshAgain=false;private TextView syncLabel;
 private final Set<Integer> expanded=new HashSet<>();
 private final Set<String> departments=new HashSet<>();
 private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 private GradientDrawable bg(int color){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(14));g.setStroke(dp(1),BORDER);return g;}
 private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
 private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);return l;}
 private TextView t(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextColor(color);v.setTextSize(size);if(bold)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setPadding(0,dp(3),0,dp(3));return v;}
 private void add(LinearLayout p,View v){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(9);p.addView(v,lp);}
 private Button btn(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(WHITE);b.setTextSize(14);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x553e7be7),bg(CARD),null));b.setMinHeight(dp(48));b.setPadding(dp(8),dp(8),dp(8),dp(8));b.setOnClickListener(v->action.run());return b;}
 private LinearLayout card(){LinearLayout l=col();l.setBackground(bg(CARD));l.setPadding(dp(14),dp(12),dp(14),dp(12));return l;}
 private void tile(LinearLayout r,String value,String label,Runnable action){Button c=btn(value+"\n"+label+"  ›",action);c.setTextSize(16);c.setMinHeight(dp(80));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),0,dp(3),0);r.addView(c,lp);}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);render();refresh();}
 @Override protected void onDestroy(){io.shutdown();super.onDestroy();}
 @Override public void onBackPressed(){if(!selected.isEmpty()){selected="";filter="";quickSection="";expanded.clear();render();}else if(!filter.isEmpty()){goHome();}else super.onBackPressed();}
 private void refresh(){if(busy){refreshAgain=true;Toast.makeText(this,"Sincronización en curso; nueva solicitud en cola",0).show();return;}busy=true;if(syncLabel!=null)syncLabel.setText("Sincronizando…");io.execute(()->{String s;try{s=BusinessSync.sync(this);}catch(Exception e){s="Error de sincronización: "+e.getMessage();}final String result=s;runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;BusinessSync.prefs(this).edit().putString("status",result).apply();if(syncLabel!=null)syncLabel.setText(result);render();Toast.makeText(this,result,0).show();if(refreshAgain){refreshAgain=false;refresh();}});});}
 private void render(){int position=scroll==null?0:scroll.getScrollY();ScrollView sc=new ScrollView(this);scroll=sc;sc.setBackgroundColor(BG);root=col();root.setPadding(dp(16),dp(18),dp(16),dp(24));sc.addView(root);setContentView(sc);sc.post(()->sc.scrollTo(0,position));
  add(root,t("VIGILANTE  •  INTELIGENCIA EMPRESARIAL",12,GREEN,true));
  add(root,t("Business Engine AI",29,WHITE,true));
  if(!selected.isEmpty()){add(root,btn("‹  Volver a proyectos",()->{selected="";quickSection="";expanded.clear();resetScroll();render();}));detail();return;}
  if(!filter.isEmpty()){showSubpage();return;}
  add(root,t("Centro de control · 27 especialistas coordinados por ChatGPT",14,MUTED,false));
  JSONArray a=BusinessSync.reports(this);int approved=0,review=0,products=0,services=0,software=0;for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);if(j==null)continue;if(isProduct(j))products++;else if(isSoftware(j))software++;else services++;if(j.optBoolean("approved"))approved++;if("ready_for_review".equals(j.optString("status")))review++;}
  LinearLayout r=row();tile(r,"27","Agentes especializados",()->showFilter("agents"));tile(r,"6","Departamentos",()->showFilter("departments"));add(root,r);
  r=row();tile(r,""+a.length(),"Proyectos",()->showFilter("all"));tile(r,""+review,"Por aprobar",()->showFilter("review"));add(root,r);
  add(root,btn("＋  Introducir producto o servicio",this::newIdea));
  add(root,btn("↻  "+(busy?"Sincronizando…":"Actualizar desde ChatGPT"),this::refresh));
  syncLabel=t(BusinessSync.prefs(this).getString("status","Pendiente de sincronización"),12,MUTED,false);add(root,syncLabel);
  r=row();tile(r,"Radar","Ideas automáticas",()->showFilter("radar"));tile(r,""+approved,"Ideas aprobadas",()->showFilter("approved"));add(root,r);
  r=row();tile(r,""+products,"Productos físicos",()->showFilter("products"));tile(r,""+services,"Servicios",()->showFilter("services"));add(root,r);r=row();tile(r,""+software,"Software / apps",()->showFilter("software"));tile(r,"PDF","Presentaciones",()->chooseProject("Presentación comercial PDF"));add(root,r);
  add(root,t("Radar: prioridad a productos físicos, sin descartar servicios.",12,MUTED,false));
  add(root,btn("Equipo de agentes · ver las 27 funciones",()->showFilter("agents")));
  add(root,t("Accesos rápidos",19,WHITE,true));
  for(String label:new String[]{"Investigaciones","Clientes potenciales","Campañas","Rentabilidad","Publicaciones","Presentación comercial PDF"})add(root,btn(label+"  ›",()->chooseProject(label)));
  add(root,t("Proyectos recientes",19,WHITE,true));listProjects("all",5);add(root,btn("Ver todos los proyectos  ›",()->showFilter("all")));
 }
 private void resetScroll(){if(scroll!=null)scroll.scrollTo(0,0);}
 private void goHome(){selected="";filter="";quickSection="";expanded.clear();departments.clear();resetScroll();render();}
 private String filterTitle(String f){switch(f){case "products":return "Productos físicos";case "services":return "Servicios";case "software":return "Software y aplicaciones";case "radar":return "Radar · ideas automáticas";case "approved":return "Ideas aprobadas";case "review":return "Por aprobar";case "agents":return "27 especialistas";case "departments":return "Departamentos";default:return "Todos los proyectos";}}
 private void showSubpage(){add(root,btn("‹  Volver al dashboard",this::goHome));add(root,t(filterTitle(filter),24,GREEN,true));if("agents".equals(filter)||"departments".equals(filter)){agentDirectory();return;}add(root,btn("Actualizar desde ChatGPT",this::refresh));listProjects(filter,0);}
 private void listProjects(String f,int limit){JSONArray a=BusinessSync.reports(this);java.util.ArrayList<JSONObject> ordered=new java.util.ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)ordered.add(x);}ordered.sort((x,y)->Boolean.compare(isProduct(y),isProduct(x)));int shown=0;for(JSONObject j:ordered){if("radar".equals(f)&&!"radar".equals(j.optString("origin")))continue;if("products".equals(f)&&!isProduct(j))continue;if("services".equals(f)&&(isProduct(j)||isSoftware(j)))continue;if("software".equals(f)&&!isSoftware(j))continue;if("review".equals(f)&&!"ready_for_review".equals(j.optString("status")))continue;if("approved".equals(f)&&!j.optBoolean("approved"))continue;projectCard(j);if(++shown==limit)break;}
 if("all".equals(f)){JSONArray pending=BusinessSync.visibleRequests(this);for(int i=0;i<pending.length();i++){JSONObject j=pending.optJSONObject(i);if(j!=null&&"submit".equals(j.optString("action"))&&BusinessSync.report(this,j.optString("projectId")).length()==0)add(root,t((j.optBoolean("sent")?"Enviado · pendiente de investigación: ":"Por enviar: ")+j.optString("title"),14,MUTED,false));}}
 if(shown==0)add(root,t("No hay proyectos en esta categoría todavía. Las búsquedas continúan cada hora.",15,MUTED,false));
 }
 private static boolean isSoftware(JSONObject j){String type=j.optString("type").toLowerCase(java.util.Locale.ROOT);return type.contains("software")||type.contains("aplicaci")||type.contains("saas");}
 private static boolean isProduct(JSONObject j){String type=j.optString("type").toLowerCase(java.util.Locale.ROOT);return type.contains("producto")||type.contains("physical")||type.equals("product");}
 private void showFilter(String f){filter=f;selected="";expanded.clear();departments.clear();resetScroll();render();}
 private void chooseProject(String section){
  JSONArray a=BusinessSync.reports(this);java.util.ArrayList<String> titles=new java.util.ArrayList<>(),ids=new java.util.ArrayList<>();
  for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null){titles.add(x.optString("title"));ids.add(x.optString("id"));}}
  if(titles.isEmpty()){new AlertDialog.Builder(this).setTitle(section).setMessage("Todavía no hay proyectos. Actualiza desde ChatGPT o introduce una idea.").setPositiveButton("Actualizar",(d,w)->refresh()).setNegativeButton("Cerrar",null).show();return;}
  new AlertDialog.Builder(this).setTitle(section+" · elige proyecto").setItems(titles.toArray(new String[0]),(d,n)->{if("Presentación comercial PDF".equals(section)){openProposal(ids.get(n));return;}selected=ids.get(n);quickSection=section;expanded.clear();departments.clear();if("Investigaciones".equals(section)){departments.add("Mercado");departments.add("Producto y finanzas");}else if("Clientes potenciales".equals(section)){departments.add("Mercado");departments.add("Ventas");expanded.add(4);expanded.add(16);}else if("Campañas".equals(section)){departments.add("Marketing");expanded.add(10);expanded.add(15);}else if("Rentabilidad".equals(section)){departments.add("Producto y finanzas");expanded.add(8);}else{departments.add("Marketing");expanded.add(12);expanded.add(13);expanded.add(14);}if(scroll!=null)scroll.scrollTo(0,0);render();}).show();
 }
 private void projectCard(JSONObject j){LinearLayout c=card();c.addView(t(j.optString("title"),19,WHITE,true));c.addView(t(j.optString("type")+" · "+j.optString("market")+" · "+j.optString("origin"),12,MUTED,false));c.addView(t(status(j.optString("status")),14,GREEN,true));JSONObject agents=j.optJSONObject("agents");int n=0;if(agents!=null)for(int k=1;k<=27;k++){JSONObject x=agents.optJSONObject(""+k);if(x!=null&&"complete".equals(x.optString("status")))n++;}ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(27);bar.setProgress(n);c.addView(bar);c.addView(t(n+"/27 informes completos",12,MUTED,false));Runnable open=()->{selected=j.optString("id");quickSection="";expanded.clear();departments.clear();departments.add("Dirección");expanded.add(27);resetScroll();render();};c.addView(btn("Abrir proyecto  ›",open));c.setOnClickListener(v->open.run());add(root,c);}
 private String status(String s){switch(s){case "ready_for_review":return "Esperando tu decisión";case "approved":return "Aprobado · preparando lanzamiento";case "rejected":return "Rechazado";case "launch_ready":return "Estrategia preparada";case "needs_validation":return "Requiere validación";default:return "En investigación";}}
 private void agentDirectory(){add(root,t("Selecciona un especialista para consultar su informe en un proyecto.",14,MUTED,false));for(String d:BusinessAgents.DEPTS){add(root,btn(d+(departments.contains(d)?"  ▴":"  ▾"),()->{if(!departments.add(d))departments.remove(d);render();}));if("departments".equals(filter)&&!departments.contains(d))continue;for(int k=0;k<27;k++){String[] a=BusinessAgents.ALL[k];if(!a[0].equals(d))continue;final int id=k+1;add(root,btn(id+". "+a[1]+(expanded.contains(id)?"  ▴":"  ▾"),()->{if(!expanded.add(id))expanded.remove(id);render();}));if(expanded.contains(id)){add(root,t(a[2],14,MUTED,false));add(root,btn("Consultar informe en proyecto  ›",()->chooseAgentProject(id)));}}}}
 private void chooseAgentProject(int agent){JSONArray a=BusinessSync.reports(this);java.util.ArrayList<String> titles=new java.util.ArrayList<>(),ids=new java.util.ArrayList<>();for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);if(j!=null){titles.add(j.optString("title"));ids.add(j.optString("id"));}}if(ids.isEmpty()){new AlertDialog.Builder(this).setMessage("Todavía no hay proyectos sincronizados.").setPositiveButton("Cerrar",null).show();return;}new AlertDialog.Builder(this).setTitle("Selecciona proyecto").setItems(titles.toArray(new String[0]),(d,n)->{selected=ids.get(n);expanded.clear();departments.clear();departments.add(BusinessAgents.ALL[agent-1][0]);expanded.add(agent);resetScroll();render();}).show();}
 private void detail(){JSONObject j=BusinessSync.report(this,selected);add(root,t(j.optString("title","Proyecto"),23,WHITE,true));add(root,t(status(j.optString("status")),15,GREEN,true));add(root,t(j.optString("summary","Investigación pendiente."),15,WHITE,false));add(root,t("Origen: "+j.optString("origin")+" · Mercado: "+j.optString("market"),12,MUTED,false));
  add(root,btn("Presentación comercial · PDF",()->openProposal(selected)));
  if(!j.optString("productSummary").isEmpty())add(root,t(j.optString("productSummary"),14,WHITE,false));
  JSONArray pending=BusinessSync.visibleRequests(this);for(int i=0;i<pending.length();i++){JSONObject x=pending.optJSONObject(i);if(x==null||!selected.equals(x.optString("projectId"))||"submit".equals(x.optString("action")))continue;JSONArray done=j.optJSONArray("processedRequestIds");boolean processed=false;if(done!=null)for(int k=0;k<done.length();k++)if(x.optString("id").equals(done.optString(k)))processed=true;if(!processed)add(root,t((x.optBoolean("sent")?"Enviado · esperando a ChatGPT: ":"En cola: ")+x.optString("action"),12,MUTED,false));}
  if(canApprove(j)){add(root,btn("✓  Aprobar y preparar marketing",()->decision("approve")));add(root,btn("Solicitar más investigación",()->decision("revise")));add(root,btn("Rechazar idea",()->decision("reject")));}
  else if(!j.optBoolean("approved")&&!"rejected".equals(j.optString("status"))){add(root,btn("Solicitar revisión",()->decision("revise")));add(root,btn("Rechazar idea",()->decision("reject")));}
  JSONObject reports=j.optJSONObject("agents");for(String d:BusinessAgents.DEPTS){add(root,btn(d+(departments.contains(d)?"  ▴":"  ▾"),()->{if(!departments.add(d))departments.remove(d);render();}));if(!departments.contains(d))continue;for(int k=0;k<27;k++){String[] a=BusinessAgents.ALL[k];if(!d.equals(a[0]))continue;int id=k+1;JSONObject report=reports==null?null:reports.optJSONObject(""+id);boolean locked=!j.optBoolean("approved")&&!BusinessAgents.pre(id);String st=locked?"Bloqueado hasta aprobación":report==null?"Pendiente":("complete".equals(report.optString("status"))?"Completo":"En investigación");add(root,btn(id+". "+a[1]+" · "+st+(expanded.contains(id)?" ▴":" ▾"),()->{if(!expanded.add(id))expanded.remove(id);render();}));if(expanded.contains(id)){LinearLayout c=card();c.addView(t(a[2],13,MUTED,false));if(locked)c.addView(t("Disponible tras la aprobación del equipo y del propietario.",14,WHITE,false));else if(report!=null){c.addView(t(report.optString("summary"),16,WHITE,true));c.addView(t(report.optString("findings"),14,WHITE,false));c.addView(t("Incertidumbre: "+report.optString("uncertainty","No indicada"),13,MUTED,false));c.addView(t("Próximos pasos: "+report.optString("nextSteps"),14,WHITE,false));JSONArray src=report.optJSONArray("sources");if(src!=null)for(int z=0;z<src.length();z++){JSONObject source=src.optJSONObject(z);if(source==null)continue;String url=source.optString("url");String title=source.optString("title",url);if(url.startsWith("https://"))c.addView(btn(title,()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(this,"No se pudo abrir",0).show();}}));}}else c.addView(t("Todavía no hay informe.",14,MUTED,false));add(root,c);}}}
  add(root,btn("Actualizar informes",this::refresh));
 }
 private void openProposal(String id){startActivity(new Intent(this,BusinessProposalActivity.class).putExtra("project",id));}
 private boolean canApprove(JSONObject j){if(!"ready_for_review".equals(j.optString("status"))||j.optBoolean("approved")||!"approve".equals(j.optString("recommendation")))return false;JSONObject a=j.optJSONObject("agents");if(a==null)return false;for(int k=1;k<=27;k++)if(BusinessAgents.pre(k)){JSONObject x=a.optJSONObject(""+k);if(x==null||!"complete".equals(x.optString("status")))return false;}return true;}
 private void decision(String action){EditText note=new EditText(this);note.setHint("Comentarios (opcional)");new AlertDialog.Builder(this).setTitle("approve".equals(action)?"Aprobar idea":"reject".equals(action)?"Rechazar idea":"Solicitar revisión").setView(note).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar",(d,w)->{try{BusinessSync.enqueue(this,action,selected,"","","",note.getText().toString());Toast.makeText(this,"Decisión guardada; pendiente de sincronización",1).show();refresh();}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}}).show();}
 private EditText field(LinearLayout f,String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(WHITE);e.setHintTextColor(MUTED);f.addView(e);return e;}
 private void newIdea(){LinearLayout f=col();f.setPadding(dp(20),dp(8),dp(20),dp(8));EditText title=field(f,"Nombre del producto o servicio");Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Producto","Servicio","Aplicación","Otro"}));f.addView(type);EditText market=field(f,"Mercado (ej. Estados Unidos)");market.setText("Estados Unidos");EditText desc=field(f,"Descripción, presupuesto, enlaces o detalles");desc.setMinLines(3);
 AlertDialog dlg=new AlertDialog.Builder(this).setTitle("Nueva idea de negocio").setView(f).setNegativeButton("Cancelar",null).setPositiveButton("Investigar",null).create();dlg.setOnShowListener(d->dlg.getButton(-1).setOnClickListener(v->{if(title.getText().toString().trim().isEmpty()){title.setError("Escribe una idea");return;}try{BusinessSync.enqueue(this,"submit","",title.getText().toString().trim(),type.getSelectedItem().toString(),market.getText().toString(),desc.getText().toString());dlg.dismiss();Toast.makeText(this,"Idea guardada; enviando a ChatGPT",0).show();render();refresh();}catch(Exception e){Toast.makeText(this,e.getMessage(),1).show();}}));dlg.show();}
}
